package com.boss.workforce.domain; import com.boss.common.domain.TenantScopedEntity; import jakarta.persistence.*; import java.time.LocalDate;
@Entity @Table(name="attrition_events") public class AttritionEvent extends TenantScopedEntity { @Column(nullable=false) private LocalDate separationDate; @Column(nullable=false,length=30) private String type; @Column(length=500) private String reason; @Column(nullable=false) private long tenureMonths; protected AttritionEvent(){} public AttritionEvent(LocalDate d,String t,String r,long m){separationDate=d;type=t;reason=r;tenureMonths=m;} public LocalDate getSeparationDate(){return separationDate;} public String getType(){return type;} public String getReason(){return reason;} public long getTenureMonths(){return tenureMonths;} }
